Definition P_ATEXIT : Z := 0x1034d0.
Definition P_ATEXIT_CALL : Z := 0x103594.     (* [comment removed for export] *)
Definition P_MUSL_LOCK : Z := 0x112504.
Definition P_MUSL_UNLOCK : Z := 0x11278c.
Definition A_ATEXIT : Z := 0x681840.          (* [comment removed for export] *)
Definition A_ATEXIT_BUILTIN : Z := 0x681858.
Definition A_NEED_LOCKS : Z := 0x681a83.     (* [comment removed for export] *)
Definition ATEXIT_FRAME : Z := 48.

(* [comment removed for export] *)
Definition AtexitCells (slot f1 a1 : Z) (f3 pad : list byte) (nx f0 : Z) (fj : list byte) (a0 : Z) (aj : list byte) : list cell :=
  [C1 (b8 0); CB 3 f3; C4 (wz 0); C4 (wz slot); CB 4 pad; C8 (wz A_ATEXIT_BUILTIN); C8 (wz nx); C8 (wz f0); C8 (wz f1); CB 240 fj; C8 (wz a0); C8 (wz a1); CB 240 aj].

Lemma AtexitCells_size : forall slot f1 a1 f3 pad nx f0 fj a0 aj,
  Z.of_nat (cells_size (AtexitCells slot f1 a1 f3 pad nx f0 fj a0 aj)) = 544.
Proof. intros. reflexivity. Qed.

