Definition atexit_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (fn : Z) (f3 pad : list byte) (nx f0 : Z) (fj : list byte) (a0 : Z) (aj : list byte) (lo : Z) (m : word -> option byte) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 0) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (A_ATEXIT, A_ATEXIT + 544)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' A_ATEXIT (AtexitCells 2 P_ATEXIT_CALL fn f3 pad nx f0 fj a0 aj).

Definition atexit_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : word -> option byte) (fn f1 a1v nx f0 a0 lo : Z) (f3 pad fj aj : list byte),
  rw_cells bsegs m A_ATEXIT (AtexitCells 1 f1 a1v f3 pad nx f0 fj a0 aj) ->
  bytes_at bsegs m A_NEED_LOCKS [b8 0] ->
  0 <= fn < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ATEXIT_FRAME <= bv_unsigned sp -> AIMG_TOP <= lo ->
  mem_inv bsegs m ->
  evt bsegs (atexit_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc fn f3 pad nx f0 fj a0 aj lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 fn) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_ATEXIT) fc None m (seg_rom bsegs)).
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.

Lemma atexit_spec : atexit_stmt.
